    @Test @Timeout(60)
    fun test_31_postOnFollowReturns200()  {
        
        val cookies_userB : Map<String,String> = given()
            .contentType("application/x-www-form-urlencoded")
            .body("username=userbb&password=userBB")
            .post("${baseUrlOfSut}/WebGoat/login")
            .then().extract().cookies()
            
        
        given().accept("*/*")
                .cookies(cookies_userB)
                .noContentType()
                .post("${baseUrlOfSut}/WebGoat/JWT/kid/follow/X")
                .then()
                .statusCode(200)
                .assertThat()
                .contentType("text/plain")
                .body(containsString("You are now following Tom"))
    }
    
    
